// === Tab: Dapple ===
function dappleOverlay() {
	dapple.background('rgb(249,234,178)');
	dapple.pixelDensity(1);
	dapple.loadPixels();
	for (let x = 0; x < floor(dapple.width); x += 1) {
		for (let y = 0; y < floor(dapple.height); y += (Math.max(0.001, Math.abs(floor(random(1, 3)) || 1)))) {
			var index = (x + y * dapple.width) * 4;
			let avalue = map(noise(x / dapple.width, y), 0, 1, 0, 32);
			dapple.pixels[index + 3] = avalue;
		}
	}
	dapple.updatePixels();
}

