// For the #WCCChallenge, and genuary2026, day 25, theme "organic geometry."
// This is an homage to Charley Harper's "Upside Down" illustration, issued in 2000,
// which depicts a nuthatch and a woodpecker perched on a tree branch.
// https://www.charleyharperartstudio.com/upside-downside-lithograph.html

let moving = true;
let hatchY = 0;
let flipX = 1;
let dapple;

function setup() {
	createCanvas(windowWidth, windowHeight);
	dapple = createGraphics(floor(height * 0.95), floor(height * 0.95));
	dappleOverlay();
	imageMode(CENTER);
	rectMode(CENTER);
	noCursor();
}

function draw() {
	if (moving) {
		hatchY = lerp(hatchY, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -height / 2, height / 2), 0.2);
		if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width / 2) flipX = -1;
		else flipX = 1;
	} else hatchY = lerp(hatchY, 0, 0.2);

	push();
	translate(width / 2, height / 2);
	push();
	background(220);
	noStroke();
	fill(255);
	rect(0, 0, height * 0.95, height * 0.95);
	scale(height / 600)
	fill('#C7C5C6');
	rect(0, 0, 478, 494);
	beginClip();
	rect(0, 0, 478, 494);
	endClip();
	drawWoodpecker();
	drawBranch();
	drawNuthatch();
	pop();
	noStroke();
	fill(255, 100);
	ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2, 20);
	image(dapple, 0, 0);
	pop();

}

function drawBranch() {
	fill('#555657');
	rect(0, 0, 160, 494);
}

function mousePressed() {
	moving = !moving;
}
